input.command:
cd C:/Users/rafal/AppData/Local/Temp/rename-bench-strict-ng-nwDnzo/workspace; npx ngc -p tsconfig.json 2>&1 | sed 's/\x1b\[[0-9;]*m//g' | grep -oE '^src[^:]+:[0-9]+:[0-9]+' | sort -t: -k1,1 -k2,2n -k3,3nr > /tmp/e.txt; wc -l /tmp/e.txt
node -e '
const fs=require("fs");const L=fs.readFileSync("/tmp/e.txt","utf8").trim().split("\n").map(x=>x.split(":"));
for(const [f,l,c] of L){const t=fs.readFileSync(f,"utf8").split("\n");const i=+l-1,k=+c-1;
if(t[i].startsWith("disableTooltip",k))t[i]=t[i].slice(0,k)+"hideHint"+t[i].slice(k+14);else console.log("miss",f,l,c);
fs.writeFileSync(f,t.join("\n"));}'
npx ngc -p tsconfig.json && echo OK

